window.AUTH=window.AUTH||{};window.AUTH["24-781"]={"d":"24-781","id":"2025/24-781","n":"First Choice Women's Resource Centers, Inc. v. Platkin","briefs":[{"k":"petitioner","label":"Brief of petitioner First Choice Women's Resource Centers, Inc.","date":"2025-08-21","url":"https://www.supremecourt.gov/DocketPDF/24/24-781/370333/20250821124925722_24-781%20Brief%20for%20Petitioner.pdf","side":"pet","n":78},{"k":"united-states","label":"Brief amicus curiae of United States","date":"2025-08-28","url":"https://www.supremecourt.gov/DocketPDF/24/24-781/373089/20250828145641364_24-781%20tsamicus%20UnitedStates.pdf","side":"us","n":98},{"k":"united-states","label":"Brief amicus curiae of United States Conference of Catholic Bishops","date":"2025-08-28","url":"https://www.supremecourt.gov/DocketPDF/24/24-781/373163/20250828185702896_First%20Choice%20v.%20Platkin%20-%20USCCB%20Amicus%20Brief.pdf","side":"us","n":38},{"k":"respondent","label":"Brief of respondent Matthew Platkin, in his official capacity as Attorney General of New Jersey","date":"2025-10-14","url":"https://www.supremecourt.gov/DocketPDF/24/24-781/379593/20251014170722015_24-781BriefForRespondent.pdf","side":"res","n":73},{"k":"reply","label":"Reply of petitioner First Choice Women's Resource Centers, Inc.","date":"2025-11-13","url":"https://www.supremecourt.gov/DocketPDF/24/24-781/384467/20251114104629030_24-781%20Reply%20Brief_Corrected.pdf","side":"pet","n":48}],"opinion":"https://www.supremecourt.gov/opinions/25pdf/608us1r30_3f14.pdf","tr":true,"items":[{"t":"case","label":"Abbott Laboratories v. Gardner","cite":"387 U.S. 136","y":1967,"id":"1966/39","sc":1,"sum":"The Court found that congress did not intend to forbid pre-enforcement review of regulations like the \"every time\" rule. The legislature designed the statute's specific review provisions to provide additional remedies for parties in Abbott Laboratories' position, not to cut down traditional channels of review. The Court remanded the case to the court of appeals.","sumSrc":"Oyez","by":{"0":"52","1":"12, 15, 16","3":"18, 35, 36, 39","4":"23"}},{"t":"case","label":"Allen v. McCurry","cite":"449 U.S. 90","y":1980,"id":"1980/79-935","sc":1,"sum":"The Court of Appeals erred in holding that respondent's inability to obtain federal habeas corpus relief upon his Fourth Amendment claim renders the doctrine of collateral estoppel inapplicable to his § 1983 suit. Nothing in the language or legislative history of § 1983 discloses any congressional intent to deny binding effect to a state-court judgment or decision when the state court, acting within its proper …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","1":"28"}},{"t":"case","label":"Americans for Prosperity Foundation v. Bonta","cite":"594 U.S. 595","y":2021,"id":"2020/19-251","sc":1,"op":11,"ar":1,"sum":"The Ninth Circuit’s judgment, which vacated the District Court’s injunction of California’s compelled disclosure of Schedule Bs as not narrowly tailored to the State’s interest in investigating charitable misconduct, is reversed, and the cases are remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"26, 31–33, 35–37, 54","1":"31, 33","2":"3, 12, 17","3":"2, 15, 26, 27, 29, 30, 32","4":"6–9, 17, 24–25"}},{"t":"case","label":"Babbitt v. Farm Workers","cite":"442 U.S. 289","y":1979,"id":"1978/78-225","sc":1,"sum":"Appellees (a farmworkers' union, a union agent, farmworkers, and a union supporter) brought suit in Federal District Court in Arizona seeking a declaration of the unconstitutionality of various provisions of Arizona's farm labor statute, as well as of the entire statute, and an injunction against \"its enforcement. A three-judge court ruled unconstitutional on various grounds the provisions (1) specifying procedures …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"48","1":"12, 14, 18, 19","3":"35"}},{"t":"case","label":"Bates v. City of Little Rock","cite":"361 U.S. 516","y":1960,"id":"1959/41","sc":1,"op":2,"ar":1,"sum":"On the record in this case, compulsory disclosure of the membership lists would work unjustified interference with the members' freedom of association, which is protected by the Due Process Clause of the Fourteenth Amendment from invasion by the States; and the convictions are reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2","2":"16","4":"10"}},{"t":"case","label":"Benham v. City of Charlotte","cite":"635 F.3d 129","y":2011,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/635/129/","by":{"0":"33"}},{"t":"case","label":"Briscoe v. LaHue","cite":"460 U.S. 325","y":1983,"id":"1982/81-1404","sc":1,"sum":"Title 42 U. S. C. § 1983 (1976 ed., Supp. V) does not authorize a convicted state defendant to assert a claim for damages against a police officer for giving perjured testimony at the defendant's criminal trial.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"28"}},{"t":"case","label":"Brown v. Kemp","cite":"86 F.4th 745","y":2023,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/86/745/","by":{"0":"34"}},{"t":"case","label":"Brown v. Socialist Workers ‘74 Campaign Committee (Ohio)","cite":"459 U.S. 87","y":1982,"id":"1982/81-776","sc":1,"op":1,"sum":"The disclosure provisions of the Ohio Campaign Expense Reporting Law requiring every candidate for political office to report the names and addresses of campaign contributors and recipients of campaign disbursements, cannot be constitutionally applied to appellee Socialist Workers Party (SWP), a minor political party that historically has been the object of harassment by Government officials and private parties.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32","2":"16","4":"6"}},{"t":"case","label":"Buckley v. Valeo","cite":"424 U.S. 1","y":1976,"id":"1975/75-436","sc":1,"op":4,"sum":"The Court held that both upheld and struck down portions of the Federal Election Campaign Act of 1971. Restrictions on individual donations were not a violation of the donators' First Amendment rights; but certain restrictions of campaign expenditures did violate the First Amendment.","sumSrc":"Oyez","by":{"0":"32–33, 35, 38, 46","2":"12, 13, 14, 16","4":"6"}},{"t":"case","label":"Citizens United v. Federal Election Commission","cite":"558 U.S. 310","y":2010,"id":"2008/08-205","sc":1,"sum":"The Court held that corporate funding of independent political broadcasts in elections cannot be limited under the First Amendment.","sumSrc":"Oyez","by":{"0":"36","2":"13, 14"}},{"t":"case","label":"Clapper v. Amnesty International USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"ar":5,"sum":"The Court held that the respondents lacked Article III standing against FISA because fear of intercepted communication and costs incurred to avoid intercepted communications are not injuries.","sumSrc":"Oyez","by":{"0":"44","1":"19, 31","3":"17, 18, 20, 23, 25, 34","4":"15"}},{"t":"case","label":"Cohens v. Virginia","cite":"19 U.S. 264","y":1821,"id":"1789-1850/19us264","sc":1,"sum":"The Court decided it had jurisdiction over all cases involving Constitutional questions, including state supreme court decisions.","sumSrc":"Oyez","by":{"0":"53"}},{"t":"case","label":"Colorado River Water Conservation District v. United States","cite":"424 U.S. 800","y":1976,"id":"1975/74-940","sc":1,"op":3,"sum":"In order to manage the allocation of water and to resolve conflicting claims thereto, Colorado enacted legislation under which the State is divided into seven Water Divisions, in each of which a procedure is established for the settlement of water claims on a continuous basis. A State Engineer is charged with responsibility for administering the distribution of state waters. Seeking adjudication of reserved rights …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 29"}},{"t":"case","label":"Dobbs v. Jackson Women’s Health Organization","cite":"597 U.S. 215","y":2022,"id":"2021/19-1392","sc":1,"sum":"The Constitution does not confer a right to abortion; Roe v. Wade, 410 U. S. 113, and Planned Parenthood of Southeastern Pa. v. Casey, 505 U. S. 833, are overruled; the authority to regulate abortion is returned to the people and their elected representatives.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"6","2":"2"}},{"t":"case","label":"Dombrowski v. Pfister","cite":"380 U.S. 479","y":1965,"id":"1964/52","sc":1,"ar":2,"sum":"Appellants, a civil rights organization and its executive director, brought suit in Federal District Court, in which other individuals later joined, for injunctive and declaratory relief to restrain appellees from prosecuting or threatening to prosecute them under Louisiana's Subversive Activities and Communist Control Law and Communist Propaganda Control Law, which they alleged violated their rights of free …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"51"}},{"t":"case","label":"Ellis v. Railway Clerks","cite":"466 U.S. 435","y":1984,"id":"1983/82-1150","sc":1,"sum":"Section 2, Eleventh of the Railway Labor Act permits a union and an employer to require all employees in the relevant bargaining unit to join the union as a condition of continued employment. The collectivebargaining agreement between respondent national union and an airline required that all of the airline's clerical employees join the union or pay agency fees equal to members' dues. Petitioners, present or former …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46"}},{"t":"case","label":"Elrod v. Burns","cite":"427 U.S. 347","y":1976,"id":"1975/74-1520","sc":1,"op":1,"sum":"The judgment is affirmed. Pp. 351-374; 374-375. 509 F. 2d 1133, affirmed. MR. JUSTICE BRENNAN, joined by MR. JUSTICE WHITE and MR. JUSTICE MARSHALL, concluded that:","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"54","4":"13"}},{"t":"case","label":"Exxon Mobil Corp. v. Healey","cite":"28 F.4th 383","y":2022,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.4th/28/383/","by":{"0":"27"}},{"t":"case","label":"Exxon Mobil Corp. v. Schneiderman","cite":"316 F. Supp. 3d 679","y":2018,"court":"S.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/316/679/","by":{"0":"27"}},{"t":"case","label":"Friends of the Earth, Inc. v. Laidlaw Environmental Services (TOC), Inc.","cite":"528 U.S. 167","y":2000,"id":"1999/98-822","sc":1,"sum":"The Court held that a citizen suitor's claim for civil penalties need not be dismissed as moot when the defendant, after commencement of the litigation, has come into compliance with its NPDES permit. \"A defendant's voluntary cessation of allegedly unlawful conduct ordinarily does not suffice to moot a case,\" Justice Ginsburg wrote for the Court. \"Congress has found that civil penalties in the Clean Water Act cases do more than promote immediate compliance... they also deter future violations,\" concluded Justice Ginsburg.","sumSrc":"Oyez","by":{"0":"45"}},{"t":"case","label":"Gibson v. Florida Legislative Investigation Committee","cite":"372 U.S. 539","y":1963,"id":"1961/6","sc":1,"op":1,"sum":"In a close decision, the Court found that Gibson's rights had been violated.","sumSrc":"Oyez","by":{"0":"2, 31–32","2":"17","3":"27"}},{"t":"case","label":"Google, Inc. v. Hood","cite":"822 F.3d 212","y":2016,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/822/212/","ar":1,"by":{"0":"3, 13, 27","1":"18","3":"6, 35, 39, 42-43"}},{"t":"case","label":"Heck v. Humphrey","cite":"512 U.S. 477","y":1994,"id":"1993/93-6188","sc":1,"sum":"The Supreme Court held that a defendant cannot claim damages for an allegedly unconstitutional conviction or imprisonment without showing that the conviction or sentence has been overturned in some way. The defendant must also exhaust state court remedies before bringing a §1983 action.","sumSrc":"Oyez","by":{"0":"4, 20","3":"45"}},{"t":"case","label":"Initiative & Referendum Institute v. Walker","cite":"450 F.3d 1082","y":2006,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/450/1082/","by":{"0":"34","4":"10"}},{"t":"case","label":"John Doe No. 1 v. Reed","cite":"561 U.S. 186","y":2010,"id":"2009/09-559","sc":1,"op":4,"sum":"The Court held that requiring the disclosure of the names of individuals who sign a referendum petition does not violate the signers' First Amendment rights to protection of political speech.","sumSrc":"Oyez","by":{"0":"36–38"}},{"t":"case","label":"Knick v. Township of Scott","cite":"588 U.S. 180","y":2019,"id":"2018/17-647","sc":1,"op":3,"ar":3,"sum":"A government violates the Takings Clause when it takes property without compensation, and a property owner may bring a Fifth Amendment claim under 42 U. S. C. §1983 at that time; the state-litigation requirement of Williamson County Regional Planning Comm’n v. Hamilton Bank of Johnson City, 473 U. S. 172, is overruled.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"4, 18, 20–21, 26, 29, 53","1":"10, 29","3":"1, 45, 46","4":"2, 19–20"}},{"t":"case","label":"Kusper v. Pontikes","cite":"414 U.S. 51","y":1973,"id":"1973/71-1631","sc":1,"sum":"Appellee, a; qualified Chicago voter who voted in a February 1971 Republican primary involving nominations for municipal officers,.. challenges the constitutionality of § 7-43 (d) of the Illinois Election Code, under which she was barred from voting in a March 1972 Democratic primary. Section 7-43 (d) prohibits a person from voting in the primary election of a political party if he has voted in the primary of any …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31"}},{"t":"case","label":"Laird v. Tatum","cite":"408 U.S. 1","y":1972,"id":"1971/71-288","sc":1,"op":1,"ar":2,"sum":"Respondents' claim that their First Amendment rights are chilled, due to the mere existence of this data-gathering system, does not constitute a justiciable controversy on the basis of the record in this case, disclosing as it does no showing of objective harm or threat of specific future harm. Pp. 3-16. 144 U. S. App. D. C. 72, 444 F. 2d 947, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30, 33, 35, 45","3":"19-23, 25","4":"15–16"}},{"t":"case","label":"Lexmark International v. Static Control Components","cite":"572 U.S. 118","y":2014,"id":"2013/12-873","sc":1,"ar":1,"sum":"The Court held that the Lanham Act allowed any party to sue for injuries relating to false advertising, as long as the party bringing suit has an interest that falls in the zone of interest that is protected by law.","sumSrc":"Oyez","by":{"0":"52","1":"16"}},{"t":"case","label":"Louisiana ex rel. Gremillion v. NAACP","cite":"366 U.S. 293","y":1961,"id":"1960/294","sc":1,"op":2,"sum":"The judgment is affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"2","3":"27"}},{"t":"case","label":"Martin v. Hunter’s Lessee","cite":"14 U.S. 304","y":1816,"id":"1789-1850/14us304","sc":1,"sum":"The Court ruled that the Supreme Court of the United States overruled the courts of the states.","sumSrc":"Oyez","by":{"0":"28–29"}},{"t":"case","label":"McNeese v. Board of Education for Community Unit School District 187","cite":"373 U.S. 668","y":1963,"id":"1962/480","sc":1,"sum":"The Court held that exhausting state remedies was not a prerequisite to bringing a suit under the Civil Rights Act.","sumSrc":"Oyez","by":{"0":"18, 22"}},{"t":"case","label":"Media Matters for America v. Paxton","cite":"138 F.4th 563","y":2025,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.4th/138/563/","op":1,"by":{"0":"25","3":"43","4":"22"}},{"t":"case","label":"MedImmune, Inc. v. Genentech, Inc.","cite":"549 U.S. 118","y":2007,"id":"2006/05-608","sc":1,"sum":"The Court reversed the Federal Circuit and ruled for MedImmune.","sumSrc":"Oyez","by":{"0":"24, 48","1":"12, 19"}},{"t":"case","label":"Meese v. Keene","cite":"481 U.S. 465","y":1987,"id":"1986/85-1180","sc":1,"sum":"The Foreign Agents Registration Act of 1938 (Act) requires registration, reporting, and disclosure by persons engaging in propaganda on behalf of foreign powers. The Act uses the term \"political propaganda\" to identify those expressive materials subject to its requirements, and defines the term as, inter alia, any communication intended to influence the United States' foreign policies. Appellee, a member of the …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","4":"11, 13"}},{"t":"case","label":"Migra v. Warren City School District Board of Education","cite":"465 U.S. 75","y":1984,"id":"1983/82-738","sc":1,"sum":"With respect to petitioner's § 1983 claim, which was not litigated in state court, petitioner's state-court judgment'has the same claim preclusive effect in federal court that the judgment would have in the Ohio state courts.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"23","3":"46"}},{"t":"case","label":"Monell v. Department of Social Services","cite":"436 U.S. 658","y":1978,"id":"1977/75-1914","sc":1,"sum":"The Court held that the legislative history of the Civil Rights Act of 1871, and specifically the Sherman Amendment, indicated that municipalities could be liable for the infringement of constitutional rights. Additionally, by 1871 there was a clear legislative and precedent-based history for municipal corporations — such as a school board — to be considered a “person” for the purpose of lawsuits and liability.","sumSrc":"Oyez","by":{"0":"20"}},{"t":"case","label":"Monroe v. Pape","cite":"365 U.S. 167","y":1961,"id":"1960/39","sc":1,"sum":"Yes and No. Justice William O. Douglas, writing for the majority, stated that the city police officers, in conducting an unreasonable search and seizure, had committed an action which was under the color of law, and that the police could be held liable individually under the Civil Rights Act. However, the majority further held that a municipality could not be liable under the Civil Rights Act.","sumSrc":"Oyez","by":{"0":"20–21, 26"}},{"t":"case","label":"Murthy v. Missouri","cite":"603 U.S. 43","y":2024,"id":"2023/23-411","sc":1,"sum":"Respondents—two States and five individual social-media users who sued Executive Branch officials and agencies, alleging that the Government pressured the platforms to censor their speech in violation of the First Amendment—lack Article III standing to seek an injunction.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"49","3":"31"}},{"t":"case","label":"NAACP v. Alabama ex rel. Patterson","cite":"357 U.S. 449","y":1958,"id":"1957/91","sc":1,"op":6,"sum":"The Court ruled that Alabama's requirement for the NAACP to divulge the names and addresses of all of its members and agents in the state violated the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"0":"2, 31–32, 35–36, 38","2":"15, 16, 18","3":"2, 26, 27, 29, 30, 46","4":"7–8, 15"}},{"t":"case","label":"NAACP v. Button","cite":"371 U.S. 415","y":1963,"id":"1962/5","sc":1,"sum":"Virginia's prosecution of the NAACP was constitutionally proscribed","sumSrc":"Oyez","by":{"0":"32–33, 51","2":"15","4":"8"}},{"t":"case","label":"National Institute for Family & Life Advocates v. James","cite":"746 F. Supp. 3d 100","y":2024,"court":"W.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/746/100/","by":{"0":"39"}},{"t":"case","label":"National Rifle Association of America v. Vullo","cite":"602 U.S. 175","y":2024,"id":"2023/22-842","sc":1,"sum":"The NRA plausibly alleged that respondent violated the First Amendment by coercing regulated entities to terminate their business relationships with the NRA in order to punish or suppress the NRA’s gun-promotion advocacy.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"34","4":"11–12"}},{"t":"case","label":"Ohio Civil Rights Commission v. Dayton Christian Schools, Inc.","cite":"477 U.S. 619","y":1986,"id":"1985/85-488","sc":1,"sum":"The Court held that federal courts should abstain from adjudicating civil state proceedings in which important state interests are involved.","sumSrc":"Oyez","by":{"0":"51","1":"12, 15"}},{"t":"case","label":"Patsy v. Board of Regents of Florida","cite":"457 U.S. 496","y":1982,"id":"1981/80-1874","sc":1,"sum":"Exhaustion of state administrative remedies is not a prerequisite to an action under § 1983.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"20, 23","1":"10, 25, 27"}},{"t":"case","label":"Pennsylvania v. West Virginia","cite":"262 U.S. 553","y":1923,"id":"scdb/1922-218","sc":1,"sum":"1. A justiciable controversy between States, in the sense of the Judiciary Article, is presented when the plaintiff State, relying on the Commerce Clause of the Constitution, seeks to enjoin the defendant State from consummating a purpose, evinced by her statutory enactment, and about to be carried out by her officials, of withdrawing natural gas from an established current of commerce moving from her territory into …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"48"}},{"t":"case","label":"Reisman v. Caplin","cite":"375 U.S. 440","y":1964,"id":"1963/119","sc":1,"op":10,"ar":2,"sum":"Petitioners have an adequate remedy at law and the complaint is properly dismissed for want of equity.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"25–27","1":"9, 23, 24","3":"38, 39, 41, 44","4":"23"}},{"t":"case","label":"Riley v. National Federation of the Blind of North Carolina, Inc.","cite":"487 U.S. 781","y":1988,"id":"1987/87-328","sc":1,"op":1,"sum":"The North Carolina Charitable Solicitations Act defines the prima facie \"reasonable fee\" that a professional fundraiser may charge according to a three-tiered schedule. A fee up to 20% of receipts collected is deemed reasonable. A fee between 20% and 35% is deemed unreasonable upon a showing that the solicitation at issue did not involve the \"dissemination of information, discussion, or advocacy relating to public …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"46–47","3":"28","4":"19"}},{"t":"case","label":"Rio Grande Foundation v. Oliver","cite":"57 F.4th 1147","y":2023,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.4th/57/1147/","by":{"0":"34"}},{"t":"case","label":"San Remo Hotel, L.P. v. City & County of San Francisco","cite":"545 U.S. 323","y":2005,"id":"2004/04-340","sc":1,"sum":"The Court rejected the argument that whenever plaintiffs reserved their federal takings claims in state court, federal courts should review the reserved federal claims, regardless of the issues decided by the state court. Moreover, federal courts were not free to disregard the full faith and credit statute simply to guarantee that all takings plaintiffs can sue in federal court.","sumSrc":"Oyez","by":{"0":"21"}},{"t":"case","label":"Shelton v. Tucker","cite":"364 U.S. 479","y":1960,"id":"1960/14","sc":1,"op":4,"ar":1,"sum":"The statute is invalid, because it deprives teachers of their right of associational freedom protected by the Due Process Clause of the Fourteenth Amendment from invasion by state action.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"31, 36","2":"16, 17, 19","4":"8, 17–18"}},{"t":"case","label":"Smith & Wesson Brands, Inc. v. Attorney General of New Jersey","cite":"105 F.4th 67","y":2024,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/105/67/","sum":"Holding Smith & Wesson’s first-filed federal claim barred by res judicata because parallel state proceedings resolved the issue first.","sumSrc":"brief:0","by":{"0":"22, 26–27","1":"28"}},{"t":"case","label":"Smith & Wesson Brands, Inc. v. Attorney General of New Jersey","cite":"27 F.4th 886","y":2022,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/27/886/","by":{"0":"22, 38, 55","3":"8, 22, 26"}},{"t":"case","label":"Speech First, Inc. v. Cartwright","cite":"32 F.4th 1110","y":2022,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.4th/32/1110/","by":{"0":"33"}},{"t":"case","label":"Speech First, Inc. v. Schlissel","cite":"939 F.3d 756","y":2019,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/939/756/","by":{"0":"33","3":"22","4":"16"}},{"t":"case","label":"Steffel v. Thompson","cite":"415 U.S. 452","y":1974,"id":"1973/72-5581","sc":1,"ar":2,"sum":"The Court held that the case presented an actual controversy, as the Georgia statute could interfere with Steffel’s exercise of his constitutional rights even if he was not arrested. Because the United States’ involvement in Vietnam, which Steffel was protesting, was reduced, the issue of whether or not the case still presented an active controversy would be decided by the lower court on remand.","sumSrc":"Oyez","by":{"0":"19","4":"6"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"op":1,"sum":"The Court held that pre-enforcement challenges are justiciable when evidence indicates that threatened enforcement of the law is sufficiently imminent.","sumSrc":"Oyez","by":{"0":"24, 29, 48–54","1":"8, 11-16","3":"18, 35, 36, 42","4":"5–6, 20–22"}},{"t":"case","label":"Talley v. California","cite":"362 U.S. 60","y":1960,"id":"1959/154","sc":1,"sum":"The ordinance is void on its face, and the conviction is reversed. Lovell v. Griffin. 303 U. S. 444. Pp. 60-66. 172 Cal. App. 2d Supp. 797, 332 P. 2d 447, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"32"}},{"t":"case","label":"Terrace v. Thompson","cite":"263 U.S. 197","y":1923,"id":"scdb/1923-029","sc":1,"sum":"1. A Washington statute (c. 50, Laws 1921,) disqualifies aliens who have not in good faith declared intention to become citizens of the United States from taking or holding interests in land -in the State for farming or other purposes not excepted, and provides that upon the making of such prohibited conveyance the land shall be forfeited to the State and the grantors be subject to criminal punishment, and the alien …","sumSrc":"Headnote (U.S. Reports)","by":{"0":"47","1":"12"}},{"t":"case","label":"Thomas v. Union Carbide Agricultural Products Co.","cite":"473 U.S. 568","y":1985,"id":"1984/84-497","sc":1,"op":5,"sum":"The Federal Insecticide, Fungicide, and Rodenticide Act (FIFRA) requires manufacturers of pesticides, as a precondition for registering a pesticide, to submit research data to the Environmental Protection Agency (EPA) concerning the product's health, safety, and environmental effects, and authorizes EPA to use previously submitted data in considering an application for registration of a similar product by another …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"30","1":"16, 26"}},{"t":"case","label":"Trinity Lutheran Church of Columbia, Inc. v. Comer","cite":"582 U.S. 449","y":2017,"id":"2016/15-577","sc":1,"op":1,"sum":"The Court determined that the exclusion of churches from an otherwise neutral and secular aid program violates the First Amendment’s guarantee of free exercise of religion.","sumSrc":"Oyez","by":{"0":"45","2":"18"}},{"t":"case","label":"Trump v. New York","cite":"592 U.S. 125","y":2020,"id":"2020/20-366","sc":1,"sum":"Because plaintiffs have not shown standing and because the claims presented are not ripe for adjudication, the District Court’s judgment is vacated, and the case is remanded with instructions to dismiss for lack of jurisdiction.","sumSrc":"Holding (supremecourt.gov)","by":{"0":"29","1":"11","3":"18, 20, 23, 25, 34, 36","4":"16"}},{"t":"case","label":"Twitter, Inc. v. Paxton","cite":"56 F.4th 1170","y":2022,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/56/1170/","ar":1,"sum":"Holding challenge ripe “even prior to” state litigation where plaintiff establishes “legally cognizable harm”.","sumSrc":"brief:0","by":{"0":"18, 25, 33","1":"18","3":"19-23, 25, 35, 38","4":"6"}},{"t":"case","label":"Village of Schaumburg v. Citizens for a Better Environment","cite":"444 U.S. 620","y":1980,"id":"1979/78-1335","sc":1,"op":1,"sum":"The Court held that charitable solicitation is not purely commercial speech and is closely related to forms of protected speech such as advocacy. Justice Byron R. White, who authored the majority opinion, argued that \"it is clear\" that charitable solicitations are protected.","sumSrc":"Oyez","by":{"0":"46","2":"14"}},{"t":"case","label":"Virginia v. American Booksellers Association, Inc.","cite":"484 U.S. 383","y":1988,"id":"1987/86-1034","sc":1,"op":1,"sum":"A 1985 amendment to a Virginia statute makes it unlawful for any person \"to knowingly display for commercial purposes in a manner whereby juveniles may examine and peruse\" certain visual or written sexual or sadomasochistic material that is harmful to juveniles. What is \"harmful to juveniles\" is defined elsewhere in the statute. Plaintiffs, a number of booksellers' organizations and two Virginia non-\"adults only,\" …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"19, 51","1":"12, 19"}},{"t":"case","label":"Warth v. Seldin","cite":"422 U.S. 490","y":1975,"id":"1974/73-2024","sc":1,"sum":"Whether the rules of standing are considered as aspects of the constitutional requirement that a plaintiff must make out a \"case or controversy\" within the meaning of Art. III, or, apart from such requirement, as prudential limitations on the courts' role in resolving disputes involving \"generalized grievances\" or third parties' legal rights or interests, none of the petitioners has met the threshold requirement of …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"34","3":"31"}},{"t":"case","label":"Watchtower Bible & Tract Society of New York, Inc. v. Village of Stratton","cite":"536 U.S. 150","y":2002,"id":"2001/00-1737","sc":1,"sum":"The Court held that the ordinance's provisions making it a misdemeanor to engage in door-to-door advocacy without first registering with the mayor and receiving a permit violate the First Amendment as it applies to religious proselytizing, anonymous political speech, and the distribution of handbills.","sumSrc":"Oyez","by":{"0":"31","2":"14"}},{"t":"case","label":"Williamson County Regional Planning Commission v. Hamilton Bank of Johnson City","cite":"473 U.S. 172","y":1985,"id":"1984/84-4","sc":1,"sum":"The Supreme Court held that even if there was a temporary taking, a decision on money damages was premature because Hamilton Bank had not obtained a final administrative decision on the subdivision layout. The claim was premature under the Due Process Clause of the Fourteenth Amendment for the same reason. Justice Byron R. White dissented from the holding that the issues in the case were not ripe for decision.","sumSrc":"Oyez","by":{"0":"20","4":"19"}},{"t":"case","label":"WinRed, Inc. v. Ellison","cite":"59 F.4th 934","y":2023,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.4th/59/934/","by":{"0":"27"}},{"t":"case","label":"Wooden v. Board of Regents of University System of Georgia","cite":"247 F.3d 1262","y":2001,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/247/1262/","by":{"0":"34"}},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"30–31","1":"6, 16, 22, 33"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1292","url":"https://www.law.cornell.edu/uscode/text/28/1292","by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1331","url":"https://www.law.cornell.edu/uscode/text/28/1331","by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 1332","url":"https://www.law.cornell.edu/uscode/text/28/1332","by":{"0":"28"}},{"t":"usc","label":"28 U.S.C. § 1738","url":"https://www.law.cornell.edu/uscode/text/28/1738","stext":{"head":"§1738. State and Territorial statutes and judicial proceedings; full faith and credit","paras":[[0,"The Acts of the legislature of any State, Territory, or Possession of the United States, or copies thereof, shall be authenticated by affixing the seal of such State, Territory or Possession thereto."],[0,"The records and judicial proceedings of any court of any such State, Territory or Possession, or copies thereof, shall be proved or admitted in other courts within the United States and its Territories and Possessions by the attestation of the clerk and seal of the court annexed, if a seal exists, together with a certificate of a judge of the court that the said attestation is in proper form."],[0,"Such Acts, records and judicial proceedings or copies thereof, so authenticated, shall have the same full faith and credit in every court within the United States and its Territories and Possessions as they have by law or usage in the courts of such State, Territory or Possession from which they are taken."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/1738?type=usc&year=mostrecent&link-type=html"},"head":"§1738. State and Territorial statutes and judicial proceedings; full faith and credit","tname":"Judiciary and Judicial Procedure","by":{"0":"21, 23","1":"28"}},{"t":"usc","label":"42 U.S.C. § 1983","url":"https://www.law.cornell.edu/uscode/text/42/1983","stext":{"head":"§1983. Civil action for deprivation of rights","paras":[[0,"Every person who, under color of any statute, ordinance, regulation, custom, or usage, of any State or Territory or the District of Columbia, subjects, or causes to be subjected, any citizen of the United States or other person within the jurisdiction thereof to the deprivation of any rights, privileges, or immunities secured by the Constitution and laws, shall be liable to the party injured in an action at law, suit in equity, or other proper proceeding for redress, except that in any action brought against a judicial officer for an act or omission taken in such officer's judicial capacity, injunctive relief shall not be granted unless a declaratory decree was violated or declaratory relief was unavailable. For the purposes of this section, any Act of Congress applicable exclusively to the District of Columbia shall be considered to be a statute of the District of Columbia."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/1983?type=usc&year=mostrecent&link-type=html"},"op":6,"ar":3,"head":"§1983. Civil action for deprivation of rights","tname":"The Public Health and Welfare","by":{"0":"3, 17","1":"1-3, 6, 8, 9, 25, 27, 28"}},{"t":"case","label":"Aetna Life Insurance Co. v. Haworth","cite":"300 U.S. 227","y":1937,"id":"scdb/1936-068","sc":1,"sum":"1. The Federal Declaratory Judgment Act deals with \"controversies\" in the constitutional sense and is procedural only.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"Atchison, Topeka & Santa Fe Railway Co., In re, v. Lopez","cite":"531 P.2d 455","y":1975,"court":"Kan.","url":"https://www.courtlistener.com/c/P.2d/531/455/","by":{"1":"17"}},{"t":"case","label":"Benson v. People","cite":"703 P.2d 1274","y":1985,"court":"Colo.","url":"https://www.courtlistener.com/c/P.2d/703/1274/","by":{"1":"17"}},{"t":"case","label":"Burlington Northern, Inc. v. Montana Department of Revenue","cite":"781 P.2d 1121","y":1989,"court":"Mont.","url":"https://www.courtlistener.com/c/P.2d/781/1121/","by":{"1":"17"}},{"t":"case","label":"(III) Cases—Continued: CC/Devas (Mauritius) Ltd. v. Antrix Corp.","cite":"145 S. Ct. 1572","y":2025,"id":"2024/23-1201","sc":1,"op":1,"sum":"To exercise personal jurisdiction over a foreign state, the Foreign Sovereign Immunities Act does not require proof of “minimum contacts” over and above the contacts already required by the Act’s enumerated exceptions to foreign sovereign immunity.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"22"}},{"t":"case","label":"Commonwealth ex rel. Hancock v. Pineur","cite":"533 S.W.2d 527","y":1976,"court":"Ky.","url":"https://www.courtlistener.com/c/S.W.2d/533/527/","by":{"1":"17"}},{"t":"case","label":"Diamond Alternative Energy, LLC v. EPA","cite":"145 S. Ct. 2121","y":2025,"id":"2024/24-7","sc":1,"op":2,"sum":"The fuel producers have Article III standing to challenge EPA’s approval under the Clean Air Act of California regulations requiring automakers to manufacture more electric vehicles and fewer gasoline-powered vehicles.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"15, 33"}},{"t":"case","label":"Evans v. State","cite":"963 P.2d 177","y":1998,"court":"Utah","url":"https://www.courtlistener.com/c/P.2d/963/177/","by":{"1":"17"}},{"t":"case","label":"FEC v. Ted Cruz for Senate","cite":"596 U.S. 289","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/289/","sc":1,"by":{"1":"32"}},{"t":"case","label":"FTC v. Claire Furnace Co.","cite":"274 U.S. 160","y":1927,"id":"scdb/1926-056","sc":1,"op":8,"ar":2,"sum":"1. An order of the Federal Trade Commission requiring a corporation to submit reports concerning its business, under § 6 of the Federal Trade Commission Act, is enforcible by the Commission only by requesting the Attorney General to institute mandamus proceedings under § 9, or by supplying him with the facts necessary to enforce the forfeiture of $100 per day, prescribed by § 10 for continued failure to ile such …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"23, 24","3":"39, 41","4":"23"}},{"t":"case","label":"FTC v. Jantzen, Inc.","cite":"386 U.S. 228","y":1967,"id":"1966/310","sc":1,"sum":"FTC orders under the Clayton Act entered before the Finality Act was enacted remain enforceable under § 11 of the Clayton Act.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"FTC v. Ruberoid Co.","cite":"343 U.S. 470","y":1952,"id":"scdb/1951-083","sc":1,"sum":"A company which was engaged in the manufacture of roofing materials was found by the Federal Trade Commission to have discriminated among customers in the prices charged for its products. The Commission held that the discriminations violated 6 2 (a) of the Clayton Act, as amended, and ordered the company to cease and desist from selling \"products of like grade and quality to any purchaser at prices lower than those …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"21"}},{"t":"case","label":"Georgia Railroad & Banking Co. v. Redwine","cite":"342 U.S. 299","y":1952,"id":"scdb/1951-032","sc":1,"sum":"Furman Smith argued'the cause for appellant. With him on the briefs was Robert B. Troutman.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Haaland v. Brackeen","cite":"599 U.S. 255","y":2023,"id":"2022/21-376","sc":1,"sum":"In child custody proceedings governed by the Indian Child Welfare Act, the Court affirms the Fifth Circuit’s conclusion that ICWA is consistent with Congress’s Article I authority, rejects petitioners’ anticommandeering challenges under the Tenth Amendment, and finds the parties lack standing to litigate their other challenges to ICWA’s placement preferences.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"27"}},{"t":"case","label":"Haywood v. Drown","cite":"556 U.S. 729","y":2009,"id":"2008/07-10374","sc":1,"sum":"The Court found that prohibiting civil claims against correction officers in their official capacities violated the Supremacy Clause of the Constitution.","sumSrc":"Oyez","by":{"1":"27"}},{"t":"case","label":"Holder v. Humanitarian Law Project","cite":"561 U.S. 1","y":2010,"id":"2009/08-1498","sc":1,"sum":"The Court held that sections of the Antiterrorism and Effective Death Penalty Act were not unconstitutionally vague in a lawsuit that named the Kurdistan Workers Party and Liberation Tigers of Tamil Eelam.","sumSrc":"Oyez","by":{"1":"12","2":"12","3":"36"}},{"t":"case","label":"Humphreys v. State ex rel. Guste","cite":"377 So. 2d 88","y":1979,"court":"La.","url":"https://www.courtlistener.com/c/So.%202d/377/88/","by":{"1":"17"}},{"t":"case","label":"Lamps Plus, Inc. v. Varela","cite":"587 U.S. 176","y":2019,"id":"2018/17-988","sc":1,"sum":"Under the Federal Arbitration Act, an ambiguous agreement cannot provide the necessary contractual basis for concluding that the parties agreed to submit to class arbitration.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"6","3":"26"}},{"t":"case","label":"Landis v. North American Co.","cite":"299 U.S. 248","y":1936,"id":"scdb/1936-018","sc":1,"sum":"(1) That to grant the stay until decision of the other case by this Court on appeal, was abuse of discretion. P. 256. (2) The question whether the stay would have been proper under the conditions which existed when it was granted, had it been granted to continue only until decision of the other case by the District Court, is a question which this Court will not decide, because the conditions have changed. P. 258. …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"33"}},{"t":"case","label":"Lane v. Wilson","cite":"307 U.S. 268","y":1939,"id":"scdb/1938-086","sc":1,"sum":"repugnant to the Fifteenth Amendment. P. 275. 98 F. 2d 980, reversed. CERTIORARI, 305 U. S. 591, to review the affirmance of a judgment, on a verdict directed for defendants in an action for damages, under R. S. 1979. LANE v. WILSON.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"27"}},{"t":"case","label":"Leedom v. Kyne","cite":"358 U.S. 184","y":1958,"id":"1958/14","sc":1,"ar":1,"sum":"A Federal District Court had jurisdiction of an original suit to set aside the Board's determination because it was made in excess of the Board's powers. Pp. 184-191. 101 U. S. App. D. C. 398, 249 F. 2d 490, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Mahmoud v. Taylor","cite":"145 S. Ct. 2332","y":2025,"id":"2024/24-297","sc":1,"sum":"Parents challenging the Montgomery County Board of Education’s introduction of certain “LGBTQ+-inclusive” storybooks, along with the Board’s decision to withhold parental opt outs from that instruction, are entitled to a preliminary injunction.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"12, 13","4":"14"}},{"t":"case","label":"Maryland Casualty Co. v. Pacific Coal & Oil Co.","cite":"312 U.S. 270","y":1941,"id":"scdb/1940-168","sc":1,"op":1,"sum":"MD. CASUALTY CO. v. PACIFIC CO.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"19"}},{"t":"case","label":"McClellan v. Carland","cite":"217 U.S. 268","y":1910,"id":"scdb/1909-133","sc":1,"sum":"The power of this court to issue writs of certiorari to the Circuit Court of Appeals is not limited to the provisions of the Court of Appeals Act. It may issue them under § 716, Rev. Stat. In re Chetwood, 165 U. S. 443; Whitney v. Dick, 202 U.-S. 132.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"29"}},{"t":"case","label":"McLaughlin Chiropractic Assocs. v. McKesson Corp.","cite":"145 S. Ct. 2006","y":2025,"id":"2024/23-1226","sc":1,"sum":"The Hobbs Act does not bind district courts in civil enforcement proceedings to an agency’s interpretation of a statute. District courts must independently determine the law’s meaning under ordinary principles of statutory interpretation while affording appropriate respect to the agency’s interpretation.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"12, 26"}},{"t":"case","label":"Medina v. Planned Parenthood South Atlantic","cite":"145 S. Ct. 2219","y":2025,"id":"2024/23-1275","sc":1,"sum":"Medicaid’s any-qualified-provider provision—42 U. S. C. §1396a(a)(23)(A)—does not clearly and unambiguously confer individual rights on Medicaid beneficiaries enforceable under 42 U. S. C. §1983.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"25"}},{"t":"case","label":"Michigan v. EPA","cite":"576 U.S. 743","y":2015,"id":"2014/14-46","sc":1,"sum":"The Court determined that the Environmental Protection Agency (EPA) unreasonably interpreted the Clean Air Act by not considering costs to power plants in deciding that regulation was “appropriate and necessary.”","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Moody v. NetChoice, LLC","cite":"603 U.S. 707","y":2023,"id":"2023/22-277","sc":1,"sum":"The judgments are vacated, and the cases are remanded, because neither the Eleventh Circuit nor the Fifth Circuit conducted a proper analysis of the facial First Amendment challenges to the Florida and Texas laws regulating large internet platforms.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"22"}},{"t":"case","label":"Morales v. Trans World Airlines, Inc.","cite":"504 U.S. 374","y":1992,"id":"1991/90-1604","sc":1,"sum":"The Court held that the Airline Deregulation Act of 1978 prevents states from prohibiting deceptive airline fare advertisements through enforcement of their general consumer protection statuses.","sumSrc":"Oyez","by":{"1":"18, 24"}},{"t":"case","label":"New Orleans Public Service, Inc. v. Council of the City of New Orleans","cite":"491 U.S. 350","y":1989,"id":"1988/88-348","sc":1,"sum":"The District Court erred in abstaining from exercising jurisdiction.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20, 29"}},{"t":"case","label":"Oklahoma Press Publishing Co. v. Walling","cite":"327 U.S. 186","y":1946,"id":"scdb/1945-112","sc":1,"op":1,"sum":"1. The Fair Labor Standards Act, as applied to the business of publishing and distributing newspapers, does not violate the First or Fifth Amendment or exceed the power of Congress under the Commerce Clause.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"20"}},{"t":"case","label":"Pakdel v. City & County of San Francisco","cite":"594 U.S. 474","y":2021,"url":"https://supreme.justia.com/cases/federal/us/594/474/","sc":1,"op":10,"by":{"1":"27","3":"25, 36, 40","4":"16"}},{"t":"case","label":"Petroleum Exploration v. Public Service Commission","cite":"304 U.S. 209","y":1938,"id":"scdb/1937-055","sc":1,"op":1,"by":{"1":"25","3":"41"}},{"t":"case","label":"Platkin v. Smith & Wesson Sales Co.","cite":"289 A.3d 481","y":2023,"court":"N.J. Super. Ct. App. Div.","url":"https://www.courtlistener.com/c/A.3d/289/481/","by":{"1":"14"}},{"t":"case","label":"Railroad & Warehouse Commission v. Duluth Street Railway Co.","cite":"273 U.S. 625","y":1927,"id":"scdb/1926-172","sc":1,"sum":"1. A public utility claiming that an order of a state commission fixing its rates deprives it of a fair return, is not bound to exhaust a statutory remedy by appeal to the state court before going into the federal court, when it is possible that such remedy might be held judicial rather than legislative in character and the decision therefore res judicata against the complainant.- J?. 627.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"28, 29"}},{"t":"case","label":"Reagan v. Farmers’ Loan & Trust Co.","cite":"154 U.S. 362","y":1894,"id":"scdb/1893-286","sc":1,"sum":"' Without passing upon the validity of the 5th and 14th sections of the act of the legislature of Texas of April 3,1891, establishing a railroad commission with power to classify and regulate rates, the remainder of the act is a valid and constitutional exercise of the state sovereignty, and the commission created thereby is an administrative board, created for carrying into effect the will of the State, as …","sumSrc":"Headnote (U.S. Reports)","by":{"1":"13"}},{"t":"case","label":"Reinman v. City of Little Rock","cite":"237 U.S. 171","y":1915,"id":"scdb/1914-073","sc":1,"sum":"The decision of the state court of last resort that a municipal ordinance is within the scope of the power conferred on the municipality by the legislature is conclusive upon this court.","sumSrc":"Headnote (U.S. Reports)","by":{"1":"23"}},{"t":"case","label":"SEC v. Jerry T. O’Brien, Inc.","cite":"467 U.S. 735","y":1984,"id":"1983/83-751","sc":1,"sum":"The SEC is not required to notify the \"targets\" of nonpublic investigations into possible violations of the securities laws when the SEC issues subpoenas to third parties. The SEC has discretion to determine when such notice would be appropriate and when it would not.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"24"}},{"t":"case","label":"Sprint Communications, Inc. v. Jacobs","cite":"571 U.S. 69","y":2013,"id":"2013/12-815","sc":1,"op":1,"sum":"The Court held that a federal court does not need to abstain from deciding a case only because there is a case in state court that deals with the same subject matter.","sumSrc":"Oyez","by":{"1":"30"}},{"t":"case","label":"State ex rel. Hager v. Carriers Insurance Co.","cite":"440 N.W.2d 386","y":1989,"court":"Iowa","url":"https://www.courtlistener.com/c/N.W.2d/440/386/","by":{"1":"17"}},{"t":"case","label":"Steel Co. v. Citizens for a Better Environment","cite":"523 U.S. 83","y":1998,"id":"1997/96-643","sc":1,"sum":"The Court held, because none of the relief sought would likely remedy its alleged injury in fact, that Citizens For A Better Environment lacked standing to maintain suit and that the Court and lower federal courts lack the jurisdiction to entertain it. While all nine Justices agreed that the organization lacked standing, they disagreed on the reasons.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Stolt-Nielsen S.A. v. AnimalFeeds International Corp.","cite":"559 U.S. 662","y":2010,"id":"2009/08-1198","sc":1,"sum":"The Court held that imposing class arbitration on parties who have not agreed to authorize class arbitration is inconsistent with the Federal Arbitration Act.","sumSrc":"Oyez","by":{"1":"16"}},{"t":"case","label":"Surefoot LC v. Sure Foot Corp.","cite":"531 F.3d 1236","y":2008,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/531/1236/","by":{"1":"20"}},{"t":"case","label":"303 Creative LLC v. Elenis","cite":"600 U.S. 570","y":2023,"id":"2022/21-476","sc":1,"sum":"The First Amendment prohibits Colorado from forcing a website designer to create expressive designs speaking messages with which the designer disagrees.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"12","3":"36"}},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"594 U.S. 413","y":2021,"id":"2020/20-297","sc":1,"op":10,"sum":"Only a plaintiff concretely harmed by a defendant’s violation of the Fair Credit Reporting Act has Article III standing to seek damages against that private defendant in federal court.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"12","3":"37"}},{"t":"case","label":"Trump v. CASA, Inc.","cite":"145 S. Ct. 2540","y":2025,"id":"2024/24a884","sc":1,"sum":"Because universal injunctions likely exceed the equitable authority that Congress has granted to federal courts, the Court grants the Government’s applications for a partial stay of the injunctions entered below regarding the implementation and enforcement of President Trump’s Executive Order No. 14160, but only to the extent that the injunctions are broader than necessary to provide complete relief to each plaintiff with standing to sue.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"13"}},{"t":"case","label":"U.S. Bancorp Mortgage Corp. v. Bonner Mall Partnership","cite":"513 U.S. 18","y":1994,"id":"1994/93-714","sc":1,"sum":"After this Court granted the petition for a writ of certiorari and received briefing on the merits, the parties entered into a settlement and agreed that the case was thereby mooted. Petitioner, however, also requested that the Court exercise its power under 28 U. S. C. § 2106 to vacate the judgment of the Court of Appeals. Respondent opposed the motion.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"32"}},{"t":"case","label":"Unnamed Attorney v. Attorney Grievance Commission","cite":"494 A.2d 940","y":1985,"court":"Md.","url":"https://www.courtlistener.com/c/A.2d/494/940/","by":{"1":"17"}},{"t":"case","label":"Vendall Marketing Corp. v. State","cite":"863 P.2d 1263","y":1993,"court":"Or.","url":"https://www.courtlistener.com/c/P.2d/863/1263/","by":{"1":"17"}},{"t":"case","label":"Virginia Office of Protection & Advocacy v. Stewart","cite":"563 U.S. 247","y":2011,"id":"2010/09-529","sc":1,"sum":"The Court held that a federal court may hear a lawsuit for prospective injunctive relief against state officials brought by another agency of the same state.","sumSrc":"Oyez","by":{"1":"26"}},{"t":"case","label":"Whole Woman’s Health v. Jackson","cite":"595 U.S. 30","y":2021,"id":"2021/21-463","sc":1,"sum":"A pre-enforcement challenge under the Federal Constitution to Texas Senate Bill 8—the Texas Heartbeat Act—may proceed past the motion to dismiss stage against certain of the named defendants but not others; the order of the District Court is affirmed in part and reversed in part, and the case is remanded.","sumSrc":"Holding (supremecourt.gov)","by":{"1":"12, 31"}},{"t":"case","label":"Younger v. Harris","cite":"401 U.S. 37","y":1971,"id":"1970/2","sc":1,"op":1,"ar":3,"sum":"In an 8-to-1 decision, the Court held that \"settled doctrines\" of federalism narrowly confined the availability of injunctive relief against state criminal prosecutions.","sumSrc":"Oyez","by":{"1":"29"}},{"t":"case","label":"Zinermon v. Burch","cite":"494 U.S. 113","y":1990,"id":"1989/87-1965","sc":1,"sum":"Burch's complaint was sufficient to state a claim under § 1983 for violation of his procedural due process rights. While Parrattand Hudson apply to deprivations of liberty, they do not preclude Burch's claim, because predeprivation procedural safeguards might have been of value in preventing the alleged deprivation of Burch's liberty without either valid consent or an involuntary placement hearing. Such a …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"25"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"1":"6, 16"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"1":"6, 16"}},{"t":"usc","label":"5 U.S.C. § 701","url":"https://www.law.cornell.edu/uscode/text/5/701","by":{"1":"3"}},{"t":"usc","label":"5 U.S.C. § 704","url":"https://www.law.cornell.edu/uscode/text/5/704","by":{"1":"23"}},{"t":"usc","label":"15 U.S.C. § 12","url":"https://www.law.cornell.edu/uscode/text/15/12","by":{"1":"21"}},{"t":"usc","label":"9 U.S.C. § 1","url":"https://www.law.cornell.edu/uscode/text/9/1","stext":{"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","paras":[[0,"\"Maritime transactions\", as herein defined, means charter parties, bills of lading of water carriers, agreements relating to wharfage, supplies furnished vessels or repairs to vessels, collisions, or any other matters in foreign commerce which, if the subject of controversy, would be embraced within admiralty jurisdiction; \"commerce\", as herein defined, means commerce among the several States or with foreign nations, or in any Territory of the United States or in the District of Columbia, or between any such Territory and another, or between any such Territory and any State or foreign nation, or between the District of Columbia and any State or Territory or foreign nation, but nothing herein contained shall apply to contracts of employment of seamen, railroad employees, or any other class of workers engaged in foreign or interstate commerce."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/9/1?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§1. \"Maritime transactions\" and \"commerce\" defined; exceptions to operation of title","tname":"Arbitration","by":{"1":"22"}},{"t":"usc","label":"9 U.S.C. § 9","url":"https://www.law.cornell.edu/uscode/text/9/9","by":{"1":"22"}},{"t":"usc","label":"9 U.S.C. § 10","url":"https://www.law.cornell.edu/uscode/text/9/10","by":{"1":"22"}},{"t":"usc","label":"5 U.S.C. § 7123","url":"https://www.law.cornell.edu/uscode/text/5/7123","subs":["(a)","(b)"],"by":{"1":"21, 21"}},{"t":"usc","label":"12 U.S.C. § 3410","url":"https://www.law.cornell.edu/uscode/text/12/3410","subs":["(a)"],"by":{"1":"23"}},{"t":"usc","label":"28 U.S.C. § 1341","url":"https://www.law.cornell.edu/uscode/text/28/1341","by":{"1":"30"}},{"t":"usc","label":"28 U.S.C. § 1342","url":"https://www.law.cornell.edu/uscode/text/28/1342","by":{"1":"30"}},{"t":"usc","label":"28 U.S.C. § 2254","url":"https://www.law.cornell.edu/uscode/text/28/2254","by":{"1":"30"}},{"t":"usc","label":"28 U.S.C. § 2283","url":"https://www.law.cornell.edu/uscode/text/28/2283","by":{"1":"30"}},{"t":"usc","label":"28 U.S.C. § 2342","url":"https://www.law.cornell.edu/uscode/text/28/2342","subs":["(1)"],"by":{"1":"22"}},{"t":"usc","label":"29 U.S.C. § 160","url":"https://www.law.cornell.edu/uscode/text/29/160","subs":["(e)"],"by":{"1":"21, 21"}},{"t":"usc","label":"47 U.S.C. § 402","url":"https://www.law.cornell.edu/uscode/text/47/402","subs":["(a)"],"by":{"1":"22"}},{"t":"usc","label":"47 U.S.C. § 503","url":"https://www.law.cornell.edu/uscode/text/47/503","subs":["(b)"],"by":{"1":"22"}},{"t":"usc","label":"47 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/47/504","subs":["(a)"],"by":{"1":"22"}},{"t":"rule","label":"Fed. R. App. P. 33","url":"https://www.law.cornell.edu/rules/frap/rule_33","by":{"1":"32"}},{"t":"rule","label":"Fed. R. Civ. P. 16","url":"https://www.law.cornell.edu/rules/frcp/rule_16","subs":["(a)(5)"],"by":{"1":"32"}},{"t":"case","label":"Bryce v. Episcopal Church","cite":"289 F.3d 648","y":2002,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/289/648/","by":{"2":"6"}},{"t":"case","label":"Cath. Charities Bureau, Inc. v. Wis. Lab. & Indus. Rev. Comm’n","cite":"605 U.S. 238","y":2025,"id":"2024/24-154","sc":1,"sum":"The Wisconsin Supreme Court’s decision denying petitioners a tax emption available to religious entities under Wisconsin law on the grounds that petitioners were not “operated primarily for religious purposes” because they neither engaged in proselytization nor limited their charitable services to Catholics violated the First Amendment.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"5, 6, 7, 11"}},{"t":"case","label":"Cha v. Korean Presbyterian Church of Washington","cite":"262 Va. 604","y":2001,"url":"https://www.courtlistener.com/c/Va./262/604/","by":{"2":"6"}},{"t":"case","label":"Conlon v. Intervarsity Christian Fellowship","cite":"777 F.3d 829","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/777/829/","sum":"Recognizing that a college campus-based Christian organization is a “‘religious group’ under Hosanna-Tabor”.","sumSrc":"brief:2","by":{"2":"7"}},{"t":"case","label":"Cornelius v. NAACP Legal Def. & Educ. Fund, Inc.","cite":"473 U.S. 788","y":1985,"id":"1984/84-312","sc":1,"sum":"By Executive Order, participation in the Combined Federal Campaign (CFC), a charity drive aimed at federal employees, is limited to voluntary, tax-exempt, nonprofit charitable agencies that provide direct health und welfare services to individuals or their families, and legal defense and political advocacy organizations are specifically excluded. Participating organizations confine their fundraising activities to a …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"14"}},{"t":"case","label":"Etienne v. Ferguson","cite":"2025 WL 2022101","y":2025,"court":"W.D. Wash. July 18","sum":"Rejecting the state’s attempt to “remove[] clergy from the [mandatory reporting law’s] privileged communication exception”.","sumSrc":"brief:2","by":{"2":"6, 7"}},{"t":"case","label":"Free Speech Coal. v. Paxton","cite":"145 S. Ct. 2291","y":2025,"id":"2024/23-1122","sc":1,"sum":"Texas law H. B. 1181—which requires certain commercial websites publishing sexually explicit content that is obscene to minors to verify that visitors are 18 or older— only incidentally burdens the protected speech of adults and survives intermediate scrutiny under the First Amendment’s Free Speech Clause.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"12"}},{"t":"case","label":"Gilmore v. City of Montgomery","cite":"417 U.S. 556","y":1974,"id":"1973/72-1517","sc":1,"sum":"Petitioners, Negro citizens of Montgomery, Ala., brought this class action in 1958 to desegregate the city's public parks, and in 1959 the District Court ordered the parks desegregated. The Court of Appeals affirmed, and ordered the District Court to retain jurisdiction. Thereafter, however, segregated recreational programs were continued by the city in cooperation with the YMCA, public swimming pools were closed …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"15"}},{"t":"case","label":"Huntsman v. Corp. of the President of the Church of Jesus Christ of Latter-Day Saints","cite":"127 F.4th 784","y":2025,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/127/784/","sum":"Recognizing the first line between church and state as occurring in the 313 A.D. Edict of Milan.","sumSrc":"brief:2","by":{"2":"5, 8"}},{"t":"case","label":"Hosanna-Tabor Evangelical Lutheran Church & Sch. v. E.E.O.C.","cite":"565 U.S. 171","y":2012,"id":"2011/10-553","sc":1,"sum":"The Court found that a woman employed by a religious school who taught daily religion classes, was a commissioned minister, and regularly lead students in prayer and worship, did not have grounds to sue the school under the Ministerial Exception.","sumSrc":"Oyez","by":{"2":"3, 5, 6, 7, 8, 13, 19"}},{"t":"case","label":"Kedroff v. St. Nicholas Cathedral of Russian Orthodox Church in N. Am.","cite":"344 U.S. 94","y":1952,"id":"scdb/1952-013","sc":1,"sum":"As thus construed and applied, the New York statute interferes with the free exercise of religion, contrary to the-First Amendment, made applicable to the states by the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"3, 5, 6, 7, 13"}},{"t":"case","label":"Kennedy v. Bremerton Sch. Dist.","cite":"597 U.S. 507","y":2022,"id":"2021/21-418","sc":1,"sum":"The Free Exercise and Free Speech Clauses of the First Amendment protect an individual engaging in a personal religious observance from government reprisal; the Constitution neither mandates nor permits the government to suppress such religious expression.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"5"}},{"t":"case","label":"Kreshik v. Saint Nicholas Cathedral","cite":"363 U.S. 190","y":1960,"id":"1959/824","sc":1,"sum":"Certiorari is granted and a decision of the Court of Appeals of New York, holding that, under the common law of New York, petitioners, as the appointees of the Patriarch of Moscow., may not exercise the right -conferred under canon law to use and occupy St. Nicholas Cathedral of the Russian Orthodox Church in New York City, is reversed on the authority of Kedroff v. St. Nicholas Cathedral, 344 U. S. 94, since the …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"5"}},{"t":"case","label":"McCutcheon v. Fed. Election Comm’n","cite":"572 U.S. 185","y":2014,"id":"2013/12-536","sc":1,"sum":"The Court ruled that the two-year aggregate campaign contribution limit of the Bipartisan Campaign Reform Act was unconstitutional.","sumSrc":"Oyez","by":{"2":"13"}},{"t":"case","label":"McIntyre v. Ohio Elections Comm’n","cite":"514 U.S. 334","y":1995,"id":"1994/93-986","sc":1,"sum":"The freedom to publish anonymously is protected by the First Amendment and \"extends beyond the literary realm to the advocacy of political causes.\" When a law burdens such anonymous speech, the Court applies \"exacting scrutiny,\" upholding the restriction only if it is narrowly tailored to serve an overriding state interest.","sumSrc":"Oyez","by":{"2":"16","4":"7"}},{"t":"case","label":"Nat’l Inst. of Fam. & Life Advocs. v. Becerra","cite":"585 U.S. 755","y":2018,"url":"https://supreme.justia.com/cases/federal/us/585/755/","sc":1,"by":{"2":"7"}},{"t":"case","label":"Our Lady of Guadalupe Sch. v. MorrisseyBerru","cite":"591 U.S. 732","y":2020,"url":"https://supreme.justia.com/cases/federal/us/591/732/","sc":1,"by":{"2":"3, 5, 6, 7, 8, 13, 19"}},{"t":"case","label":"Pulsifer v. Westshore Christian Acad.","cite":"142 F.4th 859","y":2025,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/142/859/","sum":"Noting that the Court has “eschewed any rigid formula” regarding persons qualifying for the ministerial exception, looking instead to “a variety of factors may be important” depending on the context of the employee’s role”.","sumSrc":"brief:2","by":{"2":"8"}},{"t":"case","label":"Roberts v. U.S. Jaycees","cite":"468 U.S. 609","y":1984,"id":"1983/83-724","sc":1,"op":2,"sum":"The Court held that the Jaycees chapters lacked \"the distinctive characteristics that might afford constitutional protection to the decision of its members to exclude women.\" The Court reasoned that making women full members would not impose any serious burdens on the male members' freedom of expressive association.","sumSrc":"Oyez","by":{"2":"15"}},{"t":"case","label":"Roman Cath. Diocese v. Cuomo","cite":"592 U.S. 14","y":2020,"id":"2020/20a87","sc":1,"sum":"Respondent is enjoined from enforcing Executive Order 202.68’s 10- and 25-person occupancy limits on Applicant pending disposition of the appeal in the United States Court of Appeals for the Second Circuit and disposition of the petition for a writ of certiorari, if such writ is timely sought.","sumSrc":"Holding (supremecourt.gov)","by":{"2":"6"}},{"t":"case","label":"Serbian E. Orthodox Diocese for U. S. of Am. & Canada v. Milivojevich","cite":"426 U.S. 696","y":1976,"id":"1975/75-292","sc":1,"sum":"During the course of a protracted dispute over the control of the Serbian Eastern Orthodox Diocese for the United States and Canada, the Holy Assembly of Bishops and the Holy Synod of the Serbian Orthodox Church (Mother Church) suspended and ultimately removed and defrocked the Bishop, respondent Dionisije, and appointed petitioner Firmilian as Administrator of the Diocese, which the Mother Church then reorganized …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6, 7, 13"}},{"t":"case","label":"Starkey v. Roman Cath. Archdiocese of Indianapolis, Inc.","cite":"41 F.4th 931","y":2022,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.4th/41/931/","by":{"2":"8"}},{"t":"case","label":"Watson v. Jones","cite":"80 U.S. 679","y":1871,"id":"scdb/1871-152","sc":1,"sum":"1. When in courts of concurrent jurisdiction, the pendency of a suit in one is relied on to defeat a second suit in the other, the identity cf the parties, of the case made, and of the relief sought, should be such that if the first suit had been decided it could be pleaded in bar as a former adjudication.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"5, 6, 13"}},{"t":"case","label":"Whole Woman’s Health v. Smith","cite":"896 F.3d 362","y":2018,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/896/362/","by":{"2":"8","4":"22"}},{"t":"case","label":"Arizona Students’ Ass’n v. Arizona Bd. of Regents","cite":"824 F.3d 858","y":2016,"court":"CA9","url":"https://www.courtlistener.com/c/F.3d/824/858/","op":1,"by":{"3":"20"}},{"t":"case","label":"Atlantic Richfield Co. v. FTC","cite":"546 F.2d 646","y":1977,"court":"CA5","url":"https://www.courtlistener.com/c/F.2d/546/646/","by":{"3":"39"}},{"t":"case","label":"Belle Fourche Pipeline Co. v. United States","cite":"751 F.2d 332","y":1984,"court":"CA10","url":"https://www.courtlistener.com/c/F.2d/751/332/","by":{"3":"39"}},{"t":"case","label":"Bennett v. Spear","cite":"520 U.S. 154","y":1997,"id":"1996/95-813","sc":1,"sum":"In the unanimous decision, announced by Justice Antonin Scalia, the Court ruled that the petitioners had standing to ask for judicial review of the minimum water level setting under the Endangered Species Act. The Act explicitly allows \"any person\" to sue the government over an alleged violation. Justice Scalia asserted this applies to the Secretary's actions over enforcement.","sumSrc":"Oyez","by":{"3":"40","4":"12, 20"}},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"sum":"In a 5-to-4 decision, the Court held that federal courts were without jurisdiction to entertain Lyons' claim for injunctive relief.","sumSrc":"Oyez","by":{"3":"17, 45"}},{"t":"case","label":"Counterman v. Colorado","cite":"600 U.S. 66","y":2023,"id":"2022/22-138","sc":1,"sum":"To establish that a statement is a “true threat” unprotected by the First Amendment, the State must prove that the defendant had some subjective understanding of the statements’ threatening nature, based on a showing no more demanding than recklessness.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"19"}},{"t":"case","label":"Curley v. Village of Suffern","cite":"268 F.3d 65","y":2001,"court":"CA2","url":"https://www.courtlistener.com/c/F.3d/268/65/","by":{"3":"29","4":"9"}},{"t":"case","label":"Expressions Hair Design v. Schneiderman","cite":"581 U.S. 37","y":2017,"id":"2016/15-1391","sc":1,"sum":"The Court decided that the New York General Business Law’s was not unconstitutionally vague under the Due Process Clause of the Fourteenth Amendment.","sumSrc":"Oyez","by":{"3":"26","4":"5"}},{"t":"case","label":"Exxon Mobil Corp. v. Attorney Gen.","cite":"94 N.E.3d 786","y":2018,"court":"Mass.","url":"https://www.courtlistener.com/c/N.E.3d/94/786/","by":{"3":"6"}},{"t":"case","label":"FTC v. Standard Oil Co. of Cal.","cite":"449 U.S. 232","y":1980,"id":"1980/79-900","sc":1,"sum":"The FTC's issuance of its complaint was not \"final agency action\" under § 10 (c) of the APA and hence was not judicially reviewable before the conclusion of the administrative adjudication.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"41"}},{"t":"case","label":"Food & Drug Admin. v. Alliance for Hippocratic Med.","cite":"602 U.S. 367","y":2024,"id":"2023/23-235","sc":1,"sum":"A case in which the Court was asked to resolve a challenge to the Food and Drug Administration’s 2016 and 2021 approval of the abortion drug mifepristone.","sumSrc":"Oyez","by":{"3":"17"}},{"t":"case","label":"Free Enter. Fund v. Public Co. Acct. Oversight Bd.","cite":"561 U.S. 477","y":2010,"id":"2009/08-861","sc":1,"sum":"The Court held that the Sarbanes-Oxley Act violated the Appointment Clause of the Constitution.","sumSrc":"Oyez","by":{"3":"37"}},{"t":"case","label":"Garcia v. Trenton","cite":"348 F.3d 726","y":2003,"court":"CA8","url":"https://www.courtlistener.com/c/F.3d/348/726/","by":{"3":"20"}},{"t":"case","label":"General Fin. Corp. v. FTC","cite":"700 F.2d 366","y":1983,"court":"CA7","url":"https://www.courtlistener.com/c/F.2d/700/366/","by":{"3":"39"}},{"t":"case","label":"Huffman v. Pursue, Ltd.","cite":"420 U.S. 592","y":1975,"id":"1974/73-296","sc":1,"sum":"Under the circumstances, the principles of Younger are applicable even though the state proceeding is civil in nature, and the District Court should have applied the tests laid down in Younger in determining whether to proceed to the merits and should not have entertained the action unless appellee established that early intervention was justified under the exceptions recognized in Younger, where the state …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"46"}},{"t":"case","label":"Kenny v. Wilson","cite":"885 F.3d 280","y":2018,"court":"CA4","url":"https://www.courtlistener.com/c/F.3d/885/280/","sum":"Explaining “action will be sufficiently chilling when it is likely to deter a person of ordinary firmness” from exercising First Amendment rights.","sumSrc":"brief:3","by":{"3":"20"}},{"t":"case","label":"Leeke v. Timmerman","cite":"454 U.S. 83","y":1981,"id":"1981/80-2077","sc":1,"sum":"Petitioners' actions, by which they influenced the State Solicitor's decision to oppose issuance of the arrest warrants, did not violate any judicially cognizable rights of respondents. There is a questionable nexus between respondents' injury-the alleged beatings-and the state officials' actions in which they gave information to a Magistrate prior to issuance of an arrest warrant. Even if a prosecution could remedy …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"17-18, 45"}},{"t":"case","label":"Lewis v. Casey","cite":"518 U.S. 343","y":1996,"id":"1995/94-1511","sc":1,"sum":"The Court held that the success of Casey's systemic challenge was dependent on the ability to show widespread actual injury, and the District Court's failure to identify anything more than isolated instances of actual injury rendered its finding of a systemic Bounds violation invalid.","sumSrc":"Oyez","by":{"3":"17, 45"}},{"t":"case","label":"Madison Equities, Inc. v. Office of Att’y Gen.","cite":"967 N.W.2d 667","y":2021,"court":"Minn.","url":"https://www.courtlistener.com/c/N.W.2d/967/667/","sum":"Describing Minnesota Attorney General’s subpoena power.","sumSrc":"brief:3","by":{"3":"5-6"}},{"t":"case","label":"Media Matters for Am. v. FTC","cite":"2025 WL 2378009","y":2025,"court":"D.D.C. Aug. 15","by":{"3":"38"}},{"t":"case","label":"Media Matters for Am. v. Paxton","cite":"732 F. Supp. 3d 1","y":2024,"court":"D.D.C.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/732/1/","by":{"3":"38"}},{"t":"case","label":"Mobil Expl. & Producing U.S., Inc. v. Department of Interior","cite":"180 F.3d 1192","y":1999,"court":"CA10","url":"https://www.courtlistener.com/c/F.3d/180/1192/","by":{"3":"5, 39, 43"}},{"t":"case","label":"Moody v. Michigan Gaming Control Bd.","cite":"847 F.3d 399","y":2017,"court":"CA6","url":"https://www.courtlistener.com/c/F.3d/847/399/","by":{"3":"29","4":"9"}},{"t":"case","label":"NLRB v. Uber Techs., Inc.","cite":"216 F. Supp. 3d 1004","y":2016,"court":"N.D. Cal.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/216/1004/","sum":"Noting that “the Board’s requested scope of production has shifted as a result of the meet and confer process”.","sumSrc":"brief:3","by":{"3":"43"}},{"t":"case","label":"Perdue v. Baker","cite":"586 S.E.2d 606","y":2003,"court":"Ga.","url":"https://www.courtlistener.com/c/S.E.2d/586/606/","by":{"3":"6"}},{"t":"case","label":"Ports Petroleum Co., Inc. of Ohio v. Nixon","cite":"37 S.W.3d 237","y":2001,"court":"Mo.","url":"https://www.courtlistener.com/c/S.W.3d/37/237/","by":{"3":"43"}},{"t":"case","label":"Renegotiation Bd. v. Bannercraft Clothing Co.","cite":"415 U.S. 1","y":1974,"id":"1973/72-822","sc":1,"sum":"Respondents, whose profits on defense contracts are undergoing renegotiation pursuant to the Renegotiation Act of 1951, sued in the District Court under the Freedom of Information Act (FOIA) to enjoin petitioner Board from withholding documents that respondents had requested and from conducting any further renegotiation proceedings until the documents were produced. The District Court in each case granted injunctive …","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"41"}},{"t":"case","label":"Salvation Army v. Department of Cmty. Affs.","cite":"919 F.2d 183","y":1990,"court":"CA3","url":"https://www.courtlistener.com/c/F.2d/919/183/","by":{"3":"20"}},{"t":"case","label":"Schulz v. IRS","cite":"413 F.3d 297","y":2005,"court":"CA2","url":"https://www.courtlistener.com/c/F.3d/413/297/","by":{"3":"5, 39"}},{"t":"case","label":"Seattle Pacific University v. Ferguson","cite":"104 F.4th 50","y":2024,"court":"CA9","url":"https://www.courtlistener.com/c/F.4th/104/50/","sum":"Explaining that a non-self-executing subpoena “carries no stick” and a recipient “would not face sanctions” until the recipient violates a court order compelling production.","sumSrc":"brief:3","by":{"3":"7, 22, 23, 25","4":"20–21"}},{"t":"case","label":"Shea v. Office of Thrift Supervision","cite":"934 F.2d 41","y":1991,"court":"CA3","url":"https://www.courtlistener.com/c/F.2d/934/41/","by":{"3":"39"}},{"t":"case","label":"Smith v. Plati","cite":"258 F.3d 1167","y":2001,"court":"CA10","url":"https://www.courtlistener.com/c/F.3d/258/1167/","by":{"3":"20"}},{"t":"case","label":"Spokeo, Inc. v. Robins","cite":"578 U.S. 330","y":2016,"id":"2015/13-1339","sc":1,"sum":"The Court held that lower courts need to consider the elements of Article III standing analysis separately in determining whether standing is sufficient for a federal court to hear the case.","sumSrc":"Oyez","by":{"3":"21, 37"}},{"t":"case","label":"Surita v. Hyde","cite":"665 F.3d 860","y":2011,"court":"CA7","url":"https://www.courtlistener.com/c/F.3d/665/860/","by":{"3":"20"}},{"t":"case","label":"Tafflin v. Levitt","cite":"493 U.S. 455","y":1990,"id":"1989/88-1650","sc":1,"sum":"State courts have concurrent jurisdiction over civil RICO claims. The presumption in favor of such jurisdiction has not been rebutted by any of the factors identified in Gulf Offshore Co. v. Mobil Oil Corp., 453 U. S. 473, 478.","sumSrc":"Syllabus (U.S. Reports)","by":{"3":"41"}},{"t":"case","label":"United States v. Texas","cite":"599 U.S. 670","y":2023,"id":"2022/22-58","sc":1,"sum":"Texas and Louisiana lack Article III standing to challenge immigration-enforcement guidelines promulgated by the Secretary of Homeland Security that prioritize the arrest and removal of certain noncitizens from the United States.","sumSrc":"Holding (supremecourt.gov)","by":{"3":"37, 38"}},{"t":"case","label":"Vermont Agency of Nat. Res. v. United States ex rel. Stevens","cite":"529 U.S. 765","y":2000,"id":"1999/98-1828","sc":1,"op":1,"sum":"The Court held that a private individual has standing to bring suit in federal court on behalf of the United States under the False Claims Act, but that the False Claims Act does not subject a state or state agency to liability in such actions. The Court concluded that the False Claims Act does not include states as \"persons\" who can be sued under the law.","sumSrc":"Oyez","by":{"3":"37"}},{"t":"case","label":"Wearly v. FTC","cite":"616 F.2d 662","y":1980,"court":"CA3","url":"https://www.courtlistener.com/c/F.2d/616/662/","by":{"3":"39"}},{"t":"case","label":"Br. for Appellee, Streifel v. United States","cite":"107 F.3d 24","y":1997,"court":"CA11","url":"https://www.courtlistener.com/c/F.3d/107/24/","by":{"3":"40"}},{"t":"case","label":"Br. for Missouri Attorney General, Media Matters for Am. v. Bailey","cite":"2024 WL 5097659","by":{"3":"43"}},{"t":"case","label":"Br. in Supp. of Mot. to Dismiss, Complete Merch. Sols. v. FTC","cite":"2020 WL 5371939","by":{"3":"40"}},{"t":"case","label":"Br. in Supp. of Mot. to Dismiss, Stryker Corp. v. U.S. Dep’t of Justice","cite":"2008 WL 6971058","by":{"3":"40"}},{"t":"case","label":"Bantam Books, Inc. v. Sullivan","cite":"372 U.S. 58","y":1963,"id":"1962/118","sc":1,"op":1,"ar":6,"sum":"The system of -informal censorship disclosed by this record violates the Fourteenth Amendment.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"4, 11"}},{"t":"case","label":"Bennett v. Hendrix","cite":"423 F.3d 1247","y":2005,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/423/1247/","by":{"4":"9"}},{"t":"case","label":"Cole v. Richardson","cite":"405 U.S. 676","y":1972,"id":"1971/70-14","sc":1,"sum":"The Massachusetts oath is constitutionally permissible.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"5"}},{"t":"case","label":"Dorsett v. County of Nassau","cite":"732 F.3d 157","y":2013,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/732/157/","by":{"4":"9"}},{"t":"case","label":"Federal Bureau of Investigation v. Fikre","cite":"601 U.S. 234","y":2024,"id":"2023/22-1178","sc":1,"op":1,"sum":"The Government failed to meet its burden to demonstrate that Mr. Fikre’s removal from the Government’s No Fly List mooted his 42 U. S. C. §1983 case because its declaration did not disclose the conduct that landed Mr. Fikre on the No Fly List and did not ensure that he would not be placed back on the list for engaging in the same or similar conduct in the future.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"12, 17"}},{"t":"case","label":"Grewal v. 22Mods4all Inc.","cite":"2021 WL 12167665","y":2021,"court":"N.J. Super. Ct. Ch. Div. May 24","by":{"4":"5"}},{"t":"case","label":"Lamont v. Postmaster General","cite":"381 U.S. 301","y":1965,"id":"1964/491","sc":1,"sum":"The Act as construed and applied is unconstitutional since it impos& on the addressee an affirmative obligation which amounts tou an unconstitutional limitation of his rights under the First Amendment. Pp.:305-307. 229 F. Supp. 913, reversed; 236 F. Supp. 405, affirmed.","sumSrc":"Syllabus (U.S. Reports)","by":{"4":"10"}},{"t":"case","label":"Media Matters for America v. Federal Trade Commission","cite":"2025 WL 2988966","y":2025,"court":"D.C. Cir. Oct. 23","by":{"4":"22, 24"}},{"t":"case","label":"Mendocino Environmental Center v. Mendocino County","cite":"192 F.3d 1283","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/192/1283/","by":{"4":"9"}},{"t":"case","label":"Moore v. Sims","cite":"442 U.S. 415","y":1979,"id":"1978/78-6","sc":1,"sum":"The Supreme Court held that the federal court did not have jurisdiction while the state law claims were pending. There was no indication that the state court would be unable to reach the constitutional issues themselves. Also allowing the state case to constitute did not cause any irreparable injury to the Sims, so there was no reason for ignoring Younger .","sumSrc":"Oyez","by":{"4":"4"}},{"t":"case","label":"Nieves v. Bartlett","cite":"587 U.S. 391","y":2019,"id":"2018/17-1174","sc":1,"sum":"Because police officers had probable cause to arrest Bartlett, his First Amendment retaliatory arrest claim fails as a matter of law.","sumSrc":"Holding (supremecourt.gov)","by":{"4":"9"}},{"t":"case","label":"Thompson v. North American Stainless, LP","cite":"562 U.S. 170","y":2011,"id":"2010/09-291","sc":1,"sum":"The Court held that an employer violates Title VII of the Civil Rights Acts by firing the fiancee of an employee who complains about workplace discrimination.","sumSrc":"Oyez","by":{"4":"23"}},{"t":"case","label":"Washington Post v. McManus","cite":"944 F.3d 506","y":2019,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.3d/944/506/","by":{"4":"16"}},{"t":"case","label":"White v. Lee","cite":"227 F.3d 1214","y":2000,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/227/1214/","by":{"4":"22"}}]};